[Form]
public class BDREndpointCreate extends FormRun
{
    BDREnvironment environment;
    RecId editRecId;
}

    public void init()
    {
        Common record = element.args() ? element.args().record() : null;

        if (record && record.TableId == tableNum(BDREnvironment))
        {
            environment = record;
        }
        else if (record && record.TableId == tableNum(BDREndpoint))
        {
            BDREndpoint endpoint = record;

            editRecId = endpoint.RecId;
            environment = BDREnvironment::find(endpoint.EnvironmentId);
        }

        if (!environment.RecId)
        {
            throw error("@BDR:ErrOpenFromEnvironment");
        }

        super();

        element.design().caption(strFmt('%1: %2', element.design().caption(), environment.EnvironmentId));
    }

    public void run()
    {
        super();

        // Same endpoint types as Microsoft's BusinessEventsEndpointConfiguration form.
        EndpointTypeSelection.delete(enum2Str(BusinessEventsEndpointType::CDS));
        EndpointTypeSelection.delete(enum2Str(BusinessEventsEndpointType::Flow));
        EndpointTypeSelection.delete(enum2Str(BusinessEventsEndpointType::FICAzureEndpoint));

        if (editRecId)
        {
            element.showEndpointFields();
        }
    }

/// <summary>
/// Second step: the fields of the chosen endpoint type.
/// </summary>
public void showEndpointFields()
{
    SelectTypeGroup.visible(false);
    EndpointFieldsGroup.visible(true);
    NextButton.visible(false);
    OkButton.visible(true);
    element.updateEndpointFields();
}

    /// <summary>
    /// Shows only the connection fields the endpoint type uses.
    /// </summary>
    public void updateEndpointFields()
    {
        BusinessEventsEndpointType endpointType = BDREndpoint.EndpointType;
        boolean isServiceBus = endpointType == BusinessEventsEndpointType::AzureServiceBusQueue
            || endpointType == BusinessEventsEndpointType::AzureServiceBusTopic;
        boolean hasResource = isServiceBus
            || endpointType == BusinessEventsEndpointType::AzureEventHub
            || endpointType == BusinessEventsEndpointType::AzureBlobStorage;

        BDREndpoint_ds.object(fieldNum(BDREndpoint, ResourceName)).visible(hasResource);
        BDREndpoint_ds.object(fieldNum(BDREndpoint, EndpointUrl)).visible(endpointType == BusinessEventsEndpointType::AzureEventGrid);
        BDREndpoint_ds.object(fieldNum(BDREndpoint, ServiceBusSku)).visible(isServiceBus);
        BDREndpoint_ds.object(fieldNum(BDREndpoint, EventHubSku)).visible(endpointType == BusinessEventsEndpointType::AzureEventHub);
    }

        public void init()
        {
            super();

            QueryBuildDataSource queryBuildDataSource = this.queryBuildDataSource();
            QueryBuildRange environmentRange = queryBuildDataSource.addRange(fieldNum(BDREndpoint, EnvironmentId));
            QueryBuildRange recordRange = queryBuildDataSource.addRange(fieldNum(BDREndpoint, RecId));

            environmentRange.value(queryValue(environment.EnvironmentId));
            environmentRange.status(RangeStatus::Locked);

            // Edit shows the endpoint; a new endpoint starts without a record.
            recordRange.value(queryValue(editRecId));
            recordRange.status(RangeStatus::Locked);
        }

        public void initValue()
        {
            super();

            BDREndpoint.EnvironmentId = environment.EnvironmentId;
        }

        public boolean validateWrite()
        {
            boolean ret = super();

            // Like Microsoft's endpoint setup: a new endpoint, or a changed connection, must send a test event.
            if (ret && BDREndpoint.connectionChanged())
            {
                ret = BDREndpoint.validateConnection(ValidationSecret.valueStr());
            }

            return ret;
        }

        public void clicked()
        {
            BusinessEventsEndpointType endpointType = any2Enum(EndpointTypeSelection.selection());

            super();

            BDREndpoint_ds.create();
            BDREndpoint.EndpointType = endpointType;
            element.showEndpointFields();
        }

        public void clicked()
        {
            RecId endpointRecId;
            FormRun callerForm = element.args().caller() as FormRun;

            super();

            endpointRecId = BDREndpoint.RecId;

            // Show the endpoint in the grid of the caller.
            if (endpointRecId && callerForm && formHasMethod(callerForm, identifierStr(setEndpointRecId)))
            {
                Object caller = callerForm;
                caller.setEndpointRecId(endpointRecId);
            }
        }
